SELECT p.id,p.title_cache, p.summary_cache, p.cover_media_public_id,p.content_origin_cache,p.channel_id, p.owner_user_id, p.iteration_count, p.view_count, p.like_count, p.comment_count, p.collection_count, p.hot_score, p.is_pinned, p.is_essence, p.published_at FROM post p WHERE p.visibility_status = 'PUBLISHED'
AND p.channel_id = #{q.channelId}
ORDER BY p.is_pinned DESC , p.published_at DESC , p.id DESC LIMIT #{q.offset},#{q.size}

SELECT COUNT(*) FROM post p
WHERE p.visibility_status = 'PUBLISHED'

    AND p.channel_id = #{q.channelId}
